def get_installed_distributions(
    local_only: bool = False,  # noqa: FBT001, FBT002
    user_only: bool = False,  # noqa: FBT001, FBT002
    interpreter: str | None = None,
    supplied_paths: list[str] | None = None,
) -> list[Distribution]:
    if supplied_paths:
        return filter_valid_distributions(distributions(path=supplied_paths))

    if interpreter and interpreter != sys.executable:
        # Run a subprocess to get the distributions from the specified interpreter
        cmd = [interpreter, "-c", "import sys; print(sys.path)"]
        result = subprocess.run(cmd, capture_output=True, text=True, check=True)  # noqa: S603
        paths = ast.literal_eval(result.stdout.strip())
        return filter_valid_distributions(distributions(path=paths))

    if user_only:
        return filter_valid_distributions(distributions(path=[site.getusersitepackages()]))

    # NOTE: See https://docs.python.org/3/library/venv.html#how-venvs-work for more details.
    in_venv = sys.prefix != sys.base_prefix
    if local_only and in_venv:
        venv_site_packages = site.getsitepackages([sys.prefix])
        return filter_valid_distributions(distributions(path=venv_site_packages))
    return filter_valid_distributions(distributions())
